void Save(string name, object value)
{
    var stream = new ViOStream();
    stream.Append(200);
    stream.Append("");
    if (value is PlateModelRO detail) ViSerializerInstance.Append(stream, detail);
    if (value is PageRO<PlateModelSimpleRO> page) ViSerializerInstance.Append(stream, page);
    if (value is System.Collections.Generic.List<PlateModelSimpleRO> list) ViSerializerInstance.Append(stream, list);
    File.WriteAllBytes(Path.Combine(output, name), stream.Buffer.AsSpan(0, stream.GetLength()).ToArray());
    Console.WriteLine(name + ": " + stream.GetLength() + " bytes");
}
